// items = baris 'Topik yang Sudah Ada', $node = output node sebelumnya
const pilar = $node['Ambil Pilar Konten'] || [];
const setelan = ($node['Pengaturan'] || [{}])[0] || {};
const topik = items
  .map((t) => String(t.topik || t.Topik || t.judul || '').trim())
  .filter(Boolean);

// hitung pemakaian pilar: topik diawali nama pilar, kalau tidak cocok pakai prefix sebelum ':'
const pilarDari = (t) => {
  const hit = pilar.find((p) => p && p.nama && t.toLowerCase().startsWith(String(p.nama).toLowerCase()));
  return hit ? hit.nama : t.split(':')[0].trim();
};
const dipakai = {};
for (const t of topik) {
  const k = pilarDari(t);
  dipakai[k] = (dipakai[k] || 0) + 1;
}

// pilih pilar yang paling jarang dipakai
const urut = pilar.slice().sort((a, b) => (dipakai[a.nama] || 0) - (dipakai[b.nama] || 0));
const pilih = urut[0] || { nama: setelan.pilar_default || 'Umum', id: null };
const nomor = (dipakai[pilih.nama] || 0) + 1;
const judul = pilih.nama + ' #' + nomor;

const prompt = [
  'Buat 1 ide konten untuk topik "' + judul + '".',
  'Pilar: ' + pilih.nama + (pilih.deskripsi ? ' (' + pilih.deskripsi + ')' : ''),
  'Gaya: ' + (setelan.gaya || 'bahasa manusiawi'),
  'Panjang: ' + (setelan.jumlah_kata || 300) + ' kata',
  'Jangan ulangi topik yang sudah ada: ' + (topik.length ? topik.join('; ') : '(belum ada)'),
  'Balas JSON: {"judul": "...", "ide": "..."}',
].join('\n');

return [{
  pilar: pilih.nama,
  pilar_id: pilih.id,
  judul,
  prompt,
  gaya: setelan.gaya,
  jumlah_kata: setelan.jumlah_kata,
  topik_sudah_ada: topik,
  diminta: new Date().toISOString(),
}];

// http node boleh balik { error, status, body } saat gagal (allowNon2xx)
const raw = items[0] || {};
const data = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const tugas = ($node['Susun Perintah'] || [{}])[0] || {};
const task_id = data.task_id !== undefined ? data.task_id : (data.id !== undefined ? data.id : null);
$vars.coba = ($vars.coba || 0) + 1;
return [{
  task_id,
  status: data.status || (task_id ? 'terkirim' : 'menunggu'),
  error: raw.error || null,
  percobaan: $vars.coba,
  judul: data.judul || tugas.judul || null,
  pilar: data.pilar || tugas.pilar || null,
}];

$vars.cek = ($vars.cek || 0) + 1;

const hasil = items.filter((i) => i && i.status !== 'diproses' && (i.ide || i.hasil || i.judul));
if (!hasil.length) {
  return [{ menunggu: true, jumlah: 0, putaran: $vars.cek }];
}
return hasil.map((h) => Object.assign({ menunggu: false, putaran: $vars.cek }, h));

const out = [];
for (const it of items) {
  if (!it || it.menunggu) continue;
  const ide = it.ide || it.hasil || it.konten || '';
  if (!ide) continue;
  out.push({
    dibuat: new Date().toISOString(),
    task_id: it.task_id !== undefined ? it.task_id : (it.id || ''),
    pilar: it.pilar || '',
    judul: it.judul || '',
    ide: String(ide).replace(/\s+/g, ' ').trim().slice(0, 2000),
  });
}
if (!out.length) {
  // tidak ada ide: biarkan kosong agar node berikutnya tidak menyimpan baris kosong
  return [];
}
return out;
